function bool HandleSpellLumos (optional baseSpell spell, optional Vector vHitLocation)
{
  local HPCoopGame CoopGame;
  local HPCoopWand CoopWand;

  CoopGame = HPCoopGame(Level.Game);
  if ( spell != None )
    CoopWand = HPCoopWand(spell.SpellWand);
  if ( CoopGame != None || CoopWand != None )
  {
    if ( Role != ROLE_Authority || Level.NetMode == NM_Client
      || CoopGame == None || spell == None || spell.bDeleteMe
      || spell.Class != Class'spellLumos' || CoopWand == None
      || spell.Owner != spell.Instigator || CoopWand.Owner != spell.Instigator
      || !CoopGame.IsCoopPlayer(spell.Instigator) )
      return False;
    if ( !CoopWand.ActivateCoopLumos(bMakeLumosInfinite) )
      return False;
  }
  else
  {
    baseWand(PlayerHarry.Weapon).LumosTurnOn();
    if ( bMakeLumosInfinite )
    {
      baseWand(PlayerHarry.Weapon).TheLumosLight.bInfiniteLumos = True;
    }
  }
  GotoState('Green');
  return True;
}

