function bool InLumosRadius()
{
  local HPCoopGame CoopGame;
  local HPCoopWand CoopWand;
  local LumosLight Light;
  local harry Source;

  CoopGame = HPCoopGame(Level.Game);
  if ( CoopGame != None )
  {
    if ( Role != ROLE_Authority || Level.NetMode == NM_Client )
      return False;
    foreach AllActors(Class'LumosLight', Light)
    {
      CoopWand = HPCoopWand(Light.Owner);
      if ( CoopWand == None || !Light.bLumosOn || Light.bDeleteMe )
        continue;
      Source = harry(CoopWand.Owner);
      if ( Source == None || Source.bDeleteMe || Source.Weapon != CoopWand
        || Light.PlayerHarry != Source || !CoopGame.IsCoopPlayer(Source) )
        continue;
      if ( VSize(Location - Source.Location) >= fDistanceCheck )
        continue;
      // Original Z restriction applies when entering, not when already on.
      if ( IsInState('StateWaitingToTurnOn') && bUseZDistanceCheck
        && Abs(Location.Z - Source.Location.Z) >= fZDistanceCheck )
        continue;
      PlayerHarry = Source;
      return True;
    }
    return False;
  }
  if ( VSize(Location - PlayerHarry.Location) < fDistanceCheck )
  {
    return True;
  }
  return False;
}

